async function prepareBundle(game){
  const serverMode=serverView.enabled;
  const assets=await readPublishedAssets(game,{readJSON:readSnapshotJSON,server:serverMode});
  // Discovery can finish while the first page is loading; check its release too.
  if(!serverMode&&serverView.enabled)return prepareBundle(game);
  const snapshot=game==='kpl'?normalizeSnapshot(assets.data):normalizeLolSnapshot(assets.data);
  const check=validateRows(snapshot.rows);
  if(check.errors.length)throw Error(check.errors[0]);
  if(game==='kpl')return {snapshot,catalog:null};
  const events=assets.events,catalog=assets.champions;
  if(!Array.isArray(catalog?.champions)||!catalog.champions.length||!catalog.champions.every(value=>value.id&&value.name))throw Error('英雄目录格式错误，已有数据已保留。');
  if(!Array.isArray(events?.tournaments)||!Array.isArray(events?.fixtures))throw Error('赛事日程格式错误，已有数据已保留。');
  snapshot.tournaments=events.tournaments.map(t=>({...t,teams:(t.teams||[]).map(v=>typeof v==='string'?{name:v,data_name:snapshot.metadata.teamAliases?.[v]||v}:{...v,data_name:v.data_name||snapshot.metadata.teamAliases?.[v.name]||v.code||v.name})}));
  snapshot.fixtures=[...snapshot.fixtures,...normalizeLolSnapshot({fixtures:events.fixtures}).fixtures]
    .filter((f,i,all)=>['demacia','worlds'].includes(f.tournament_id||f.tournament)&&Date.parse(f.date)>=Date.now()&&all.findIndex(v=>v.id===f.id)===i)
    .sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));
  return {snapshot,catalog};
}
async function loadBundle(game){
  const {snapshot,catalog}=await prepareBundle(game);
  if(catalog)state.championCatalog=catalog;
  return snapshot;
}
async function loadGame(game){
  const version=serverVersions[game];
  let bundled=serverSnapshots[game]||null,error=null;try{bundled=bundled||await loadBundle(game);}catch(e){error=e;}
  if(version!==serverVersions[game])return loadGame(game);
  let snapshot=bundled||{rows:[],fixtures:[],metadata:{},tournaments:[]},source='official',customFixtures=[];
  try{const saved=JSON.parse(localStorage.getItem(`${game}-observer-v1`)||'null');
    if(saved?.snapshot?.rows?.length&&(saved.source==='import'||saved.snapshot.rows.every(r=>r.available_at))&&(!bundled||saved.source==='import'||Date.parse(saved.snapshot.metadata.fetchedAt||saved.snapshot.metadata.syncedAt)>Date.parse(bundled.metadata.fetchedAt||bundled.metadata.syncedAt))){snapshot=saved.snapshot;source=saved.source||'import';if(game==='lol'&&bundled){snapshot={...snapshot,fixtures:bundled.fixtures,tournaments:bundled.tournaments};}}
    customFixtures=(saved?.customFixtures||[]).filter(f=>f.teamA&&f.teamB&&f.date);
  }catch{}
  return {snapshot,source,customFixtures,error};
}
async function switchGame(game){
  if(state.updating||state.loading||state.game===game||!['kpl','lol'].includes(game))return;
  clearTimeout(lineTimer);$('#modal').innerHTML='';
  const keys=['snapshot','source','customFixtures','selected','durationLine','killsLine','handicap','backtest','tournament','lookback','map','predictionMode','draftBacktest','leagueFilter'];
  gameBank[state.game]=Object.fromEntries(keys.map(k=>[k,state[k]]));
  Object.assign(state,{game,predictionMode:'pre',draftBacktest:null,selected:0,loading:true,query:'',event:'all',leagueFilter:'all',page:0,map:'all',backtest:null,tournament:'all',lookback:90,durationLine:game==='lol'?32.5:18.5,killsLine:game==='lol'?26.5:24.5,handicap:3.5});render();
  const data=gameBank[game]||await loadGame(game);Object.assign(state,data,{loading:false});
  try{localStorage.setItem('esports-active-game',game);}catch{}
  render();if(data.error)toast('部分数据未加载成功，可点击刷新重试。');
}
async function refreshLol(){
  state.updating=true;render();try{
    const snapshot=await loadBundle('lol'),check=validateRows(snapshot.rows);if(check.errors.length)throw Error(check.errors[0]);
    state.snapshot=snapshot;state.source='official';state.backtest=null;state.draftBacktest=null;state.selected=0;saveLocal();
    toast(`已载入最新发布快照，共 ${snapshot.rows.length} 局；数据采集日期见页面。`);
  }catch(e){toast(`刷新未完成：${e.message}，保留已有数据。`);}finally{state.updating=false;render();}
}
