const DRAFT_ROLES=[['top','上单'],['jungle','打野'],['mid','中单'],['bottom','下路'],['support','辅助']];
const draftKey=(f=current())=>f?JSON.stringify([f.id,f.teamA,f.teamB,f.date,state.map]):'';
const emptyDraft=()=>({teamA:{},teamB:{}});
const currentDraft=()=>state.drafts[draftKey()]||emptyDraft();
