function saveDraftChoices(){try{localStorage.setItem('lol-hero-drafts-v1',JSON.stringify(Object.fromEntries(Object.entries(state.drafts).slice(-100))));}catch{}}
function applyDraft(){if(!draftValidation().valid){toast('请选择完整且不重复的 10 名英雄。');return;}state.appliedDrafts[draftKey()]=JSON.parse(JSON.stringify(currentDraft()));saveDraftChoices();render();}
function clearDraft(){delete state.drafts[draftKey()];delete state.appliedDrafts[draftKey()];state.championPicker=null;saveDraftChoices();render();$('#champion-picker-title')?.focus({preventScroll:true});}
function draftBacktestSection(){
  if(state.game!=='lol')return '';
  const b=state.draftBacktest;
  return `<section class="panel panel-pad draft-backtest"><div class="panel-heading"><div><h2>选英雄前后，误差是否改变？</h2><p class="sub">使用相同历史比赛进行配对比较</p></div>${button('比较两种模式','compare-draft','chart','primary small')}</div><p class="backtest-description">取最近最多 60 局有完整阵容的比赛。每次重建赛前模型，排除整个目标系列赛及当时尚未结束的比赛；两个模式使用同一组可验证样本。回看窗口沿用预测工作台设置。英雄信息按该局已经完成选人处理。</p>${draftBacktestResults(b)}</section>`;
}
function draftBacktestResults(b){
  if(!b)return '<p class="empty">运行对照回测后，查看加入英雄信息是否降低了历史误差。不会预设阵容模式一定更准。</p>';
  if(!b.available)return `<p class="empty">${esc(b.error||'可比较的历史样本不足。')}</p>`;
  const before=b.baseline?.mae||{},after=b.draft?.mae||{};
  return `<p class="draft-validation-count">共同验证 ${b.count} 局 · 其中 ${b.appliedCount||0} 局启用阵容修正、${b.fallbackCount||0} 局回退基线 · 跳过 ${b.skipped||0} 局。MAE 越小越好。</p><div class="table-scroll"><table><thead><tr><th>指标</th><th>赛前 MAE</th><th>阵容 MAE</th><th>本次变化</th></tr></thead><tbody>${[['时长 / 分钟','durationMin'],['总击杀','totalKills'],['A 队击杀差','killDiff']].map(([label,k])=>{const delta=after[k]-before[k];return `<tr><td>${label}</td><td>${fmt(before[k],2)}</td><td>${fmt(after[k],2)}</td><td>${Number.isFinite(delta)?`${delta>0?'增加':delta<0?'降低':'持平'} ${fmt(Math.abs(delta),2)}`:'—'}</td></tr>`;}).join('')}</tbody></table></div><div class="paired-coverage"><h3>80% 区间的实际覆盖率</h3><div class="table-scroll"><table><thead><tr><th>指标</th><th>赛前模式</th><th>阵容模式</th></tr></thead><tbody>${[['时长','durationMin'],['总击杀','totalKills'],['击杀差','killDiff']].map(([label,k])=>`<tr><td>${label}</td><td>${pct(b.baseline?.coverage80?.[k])}</td><td>${pct(b.draft?.coverage80?.[k])}</td></tr>`).join('')}</tbody></table></div></div><p class="backtest-description">这些差异仅描述当前测试样本，不证明未来表现。尚未独立校准大小概率，也不能从 MAE 推断命中率。</p>${button('下载对照结果','export-draft-backtest','download','small')}`;
}
function runDraftBacktest(){
  const el=document.querySelector('[data-action="compare-draft"]');if(el){el.disabled=true;el.textContent='正在比较…';}
  const rows=modelRows(),game=state.game,lookback=state.lookback;
  setTimeout(()=>{if(state.game!==game)return;try{state.draftBacktest=compareDraftBacktest(rows,{game:'lol',season:'2026',lookback,limit:60,date:new Date().toISOString()});render();}catch(e){toast(e.message);render();}},30);
}
function draftMethod(){if(state.game!=='lol')return '';return `<section class="panel method-card" style="margin-top:20px"><div class="num">05 / CHAMPION DRAFT</div><h3>两种模式，同一套历史基线</h3><p>赛前预测只使用战队历史数据。阵容确定后模式在相同赛前基线上，跨局序学习英雄与位置对时长、总击杀和击杀差的残差修正；使用固定岭收缩，稀有英雄影响趋近于零，未见英雄不编造修正。</p><p>双方每个位置必须选择英雄，本局 10 个英雄不能重复。输入仅属于所选场次和局序。英雄名单来自官方 Data Dragon 中文目录（${esc(state.championCatalog.version||'待加载')}），目录版本不代表目标比赛版本；历史位置来自该局官方位置字段，不按英雄类型或选手数组顺序推断。</p><p>仅使用开赛前已结束且有完整阵容记录的 LoL 历史。没有足够训练样本时回退为赛前参考并明确标记。区间不因为新增英雄特征而自行缩窄，概率仍未校准。回测页可对比相同比赛上的两种模式误差；不预设准确率提升。</p></section>`;}


const REGIONS={LPL:'LPL · 中国',LCK:'LCK · 韩国',LEC:'LEC · 欧洲',LCS:'LCS · 北美',LCP:'LCP · 亚太',CBLOL:'CBLOL · 巴西'};
const leagueCode=r=>String(r.league||'未分类').toUpperCase();
const regionLabel=code=>REGIONS[code]||code;
function rowDateLabel(r){if(r.date_basis==='unknown_timezone_upper_bound'&&r.scheduled_at)return esc(dateLabel(r.scheduled_at))+'<small class="date-qualifier">官方计划时间</small>';return r.date_basis==='unknown_timezone_upper_bound'?`<span title="源数据未注明时区，此处保留原始日期；预测使用保守时间界限">${esc(String(r.source_date_raw||'').slice(0,10))}</span><small class="date-qualifier">时区待核</small>`:esc(dateLabel(r.date))+(/schedule/.test(r.date_basis||'')?'<small class="date-qualifier">官方计划时间</small>':'');}
function regionalCoverage(rows){
  if(state.game!=='lol')return '';
  const unknown=rows.filter(r=>r.series_verified===false),observed=rows.filter(r=>r.availability_basis==='observed_snapshot');
  return `<section class="panel regional-panel"><div class="panel-heading"><div><span class="eyebrow">REGIONAL COVERAGE</span><h2>主要赛区历史数据</h2></div><span class="sub">2026 年已收录逐局记录</span></div><div class="regional-grid">${Object.entries(REGIONS).map(([code,label])=>{const games=rows.filter(r=>leagueCode(r)===code),teams=new Set(games.flatMap(r=>[r.team_a,r.team_b])),dates=games.map(r=>(r.source_date_raw||r.date||'').slice(0,10)).sort(),coverage=(state.snapshot.metadata.globalRegions?.competitions||[]).find(c=>c.league===code),missing=Math.max(0,(coverage?.expected_maps||games.length)-games.length);return `<button class="region-card ${state.leagueFilter===code?'selected':''}" data-region="${code}" aria-label="筛选${label}"><span>${label}</span><strong>${games.length.toLocaleString()}<small> 局</small></strong><p>${teams.size} 支战队${missing?` · <span class="warn">缺 ${missing} 局</span>`:''}</p><small>${dates.length?`截至 ${esc(dates.at(-1))}`:'暂无逐局数据'}</small></button>`;}).join('')}</div><p class="regional-note">国际赛事另计；点击赛区查看逐局记录。${unknown.length?`有 ${unknown.length} 局系列赛归属待核，已保留时长、击杀和阵容，不计入完整系列赛数量。`:''}${observed.length?` ${observed.length} 局按首次采集时间启用，可用于此后的预测，不参与历史时点回测。`:''}</p>${state.source==='official'&&observed.length?'<a class="regional-attribution" href="https://chaincc.lol/free/data" target="_blank" rel="noopener noreferrer">补充来源：ChainCC / Oracle’s Elixir · CC BY 4.0 ↗</a>':''}</section>`;
}
function unlinkedRecent(f,team){
  if(state.game!=='lol')return '';
  const maps=recentUnlinkedMaps(modelRows(),{team,date:f.date,excludeSeriesId:f.id,limit:20});if(!maps.length)return '';
  return `<details class="unlinked-recent"><summary>系列赛归属待核的近期逐局记录 · ${maps.length} 局</summary><p>以下数据可用于当前预测；尚未关联到完整系列赛，不占用上方近 20 场名额，也不计整场胜负。</p><div class="table-scroll"><table><thead><tr><th>源记录日期</th><th>赛事 / 对手</th><th>局序</th><th>时长</th><th>本队 : 对手击杀</th><th>来源</th></tr></thead><tbody>${maps.map(r=>`<tr><td>${rowDateLabel(r)}</td><td>${esc(r.league||'')} · ${esc(r.team_a===team?r.team_b:r.team_a)}</td><td>G${r.map}</td><td>${duration(r.duration_sec)}</td><td>${r.ownKills} : ${r.opponentKills}</td><td>${sourceLinks(r)}</td></tr>`).join('')}</tbody></table></div></details>`;
}

async function init(){
  try{if((new URLSearchParams(location.search).get('game')||localStorage.getItem('esports-active-game'))==='lol'){state.game='lol';state.durationLine=32.5;state.killsLine=26.5;}}catch{}
  try{const saved=JSON.parse(localStorage.getItem('lol-hero-drafts-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved)){for(const [key,value] of Object.entries(saved).slice(-100)){if(key.length>600||!value||typeof value!=='object')continue;const d=emptyDraft();for(const side of ['teamA','teamB'])for(const [role] of DRAFT_ROLES){const id=value[side]?.[role];if(typeof id==='string'&&/^[A-Za-z][A-Za-z0-9]*$/.test(id))d[side][role]=id;}state.drafts[key]=d;}}}catch{}
  Object.assign(state,await loadGame(state.game),{loading:false});render();
  if(!state.snapshot.rows.length)toast('当前尚无可用逐局快照，请刷新数据或导入 CSV。');
}
render();init();void serverClient.detect();
